function graphemeSegments(text) {
  if (typeof Intl !== 'undefined' && typeof Intl.Segmenter === 'function') {
    return Array.from(
      new Intl.Segmenter("en", { granularity: 'grapheme' }).segment(text),
      (item) => item.segment
    );
  }
  return Array.from(text.normalize('NFC'));
}

function countWords(text) {
  if (typeof Intl !== 'undefined' && typeof Intl.Segmenter === 'function') {
    return Array.from(
      new Intl.Segmenter("en", { granularity: 'word' }).segment(text)
    ).filter((item) => item.isWordLike).length;
  }
  const words = text.match(/[\p{L}\p{N}]+(?:['’][\p{L}\p{N}]+)*/gu);
  return words ? words.length : 0;
}

function process(data) {
  const text = data.selection;
  const graphemes = graphemeSegments(text);
  const nonWhitespace = graphemes.filter((segment) => !/\s/u.test(segment)).length;
  const lines = text === '' ? 0 : text.split(/\r\n|\r|\n/).length;
  const bytes = new TextEncoder().encode(text).length;

  return [
    "Graphemes: " + graphemes.length,
    "Non-whitespace characters: " + nonWhitespace,
    "Words: " + countWords(text),
    "Lines: " + lines,
    "UTF-8 bytes: " + bytes
  ].join('\n');
}
